from pathlib import Path
import shutil,json
root=Path('dist/projects');root.mkdir(exist_ok=True)
projects=[
('flowboard','Flowboard','Productivity','A focused workspace for turning a backlog into finished work. Add tasks, prioritise them, and move work through three stages.','State management · Local persistence · Search & filtering','Local-only task board; no team synchronisation or accounts.'),
('data-lens','Data Lens','Data','Turn a CSV file into a readable statistical snapshot. Explore a column, compare values and inspect the underlying records.','CSV parsing · Descriptive statistics · Data visualisation','Files are processed in your browser. Charts show the first 24 numeric values; no data is uploaded.'),
('route-lab','Route Lab','Algorithms','Build obstacles and watch breadth-first and depth-first search explore a grid. Compare their paths, one step at a time.','Graph traversal · Algorithm animation · Interactive state','Unweighted, four-directional grid. BFS finds a shortest path; DFS does not guarantee one.'),
('contrast-studio','Contrast Studio','Design tools','Find colour combinations that stay readable. Preview your palette and measure text contrast as you design.','Colour science · Accessible UI · CSS token export','Checks colour contrast only, not complete accessibility compliance. Normal-text AA threshold: 4.5:1.'),
('focus-studio','Focus Studio','Productivity','Give one task your full attention. Set a session, start the clock, and keep a simple record of the work you complete.','Deadline-based timing · Local storage · Session history','Sessions are stored in this browser. No notifications, cloud sync or background alarms.'),
('slotwise','Slotwise','Productivity','Plan a personal schedule without double-booking. Create appointments, detect overlaps and export your agenda to a calendar.','Interval validation · Calendar export · CRUD workflows','A single-person local planner. No live availability, shared bookings or email delivery.')]
for slug,name,category,desc,skills,limit in projects:
 p=root/slug;p.mkdir(exist_ok=True)
 shutil.copy('scripts/core.mjs',p/'core.js');shutil.copy('scripts/app.css',p/'styles.css')
 (p/'index.html').write_text(f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#202a25"><meta name="description" content="{desc}"><title>{name} — Seloana Web Architects</title><link rel="stylesheet" href="./styles.css"></head><body><header><a href="../../index.html#work">← Seloana Web Architects</a><span>PROJECT LAB / {category.upper()}</span></header><main><span class="eyebrow">Interactive project · Built to explore</span><h1>{name}</h1><p class="intro">{desc}</p><div id="app"></div><p id="status" role="status" aria-live="polite"></p><footer class="foot"><details><summary>Engineering notes & scope</summary><p>{skills}</p><p>{limit}</p><p>Implementation: semantic HTML, responsive CSS and modular JavaScript. No external runtime dependencies.</p></details><p><a href="../../source/{slug}.zip" download>Download source ↗</a><a href="../../index.html#work">Back to portfolio</a></p></footer></main><script type="module" src="./app.js"></script></body></html>''')
 (p/'README.md').write_text(f'''# {name}\n\n{desc}\n\n## Demonstrated skills\n{skills}\n\n## Run\nRun `python3 -m http.server 8080` in this directory, then open http://localhost:8080. Serve over HTTP; JavaScript modules do not load reliably from file://.\n\n## Deploy independently\nUpload this directory to any static host. For GitHub Pages, publish the repository root. Back-to-portfolio and source-download links are relative to the parent showcase; replace those two links for a standalone deployment.\n\n## Scope\n{limit}\n\n## Files\n- index.html: semantic page shell\n- styles.css: responsive design\n- app.js: project interactions\n- core.js: shared pure functions and browser helpers\n\nSample records are fictional. No API keys or server are required.\n''')
Path('scripts/projects.json').write_text(json.dumps(projects))
